/**
 * The catalog palette: twenty tones in one family, each in three steps.
 *
 * Seventeen hues around the wheel at one lightness, plus three greys that lean (neutral,
 * slate, stone) so an idle ladder can still hold three distinct steps. Every tone is a tint,
 * an ink and a dot (`--color-tag-<tone>-bg|fg|dot`, generated by `scripts/tag-palette.mjs`);
 * a step deepens all three, which is how a catalog longer than the palette stays without
 * repeats. Stored on a catalog value as its `colour`: `blue`, `blue-2`, `blue-3`.
 */

/** Wheel order — the spacing the nominal sequence steps through. */
export const TAG_HUES = [
  'rose',
  'red',
  'orange',
  'amber',
  'yellow',
  'lime',
  'green',
  'emerald',
  'teal',
  'cyan',
  'sky',
  'blue',
  'indigo',
  'violet',
  'purple',
  'fuchsia',
  'pink',
] as const

export const TAG_NEUTRALS = ['neutral', 'slate', 'stone'] as const

export type TagHue = (typeof TAG_HUES)[number]
export type TagTone = TagHue | (typeof TAG_NEUTRALS)[number]
export type TagTier = 1 | 2 | 3
export type TagColour = { tone: TagTone; tier: TagTier }

export const TAG_TONES: readonly TagTone[] = [...TAG_HUES, ...TAG_NEUTRALS]
export const TAG_TIERS: readonly TagTier[] = [1, 2, 3]

/**
 * Names written before this palette, by the seeds (`next_steps_state`, `sdr_stage`,
 * `guest_rsvp`) and by the earlier eight-tone chip set, so a stored colour keeps its hue.
 */
const ALIASES: Record<string, TagTone> = {
  peach: 'orange',
  gold: 'yellow',
  gray: 'neutral',
  grey: 'neutral',
  info: 'blue',
  azure: 'blue',
  success: 'green',
  mint: 'emerald',
  warning: 'amber',
  danger: 'red',
  flame: 'orange',
}

export function isTagTone(value: string): value is TagTone {
  return (TAG_TONES as readonly string[]).includes(value)
}

/** `blue`, `blue-2`, a legacy `gold` → the colour; anything else (a hex, a typo) → null. */
export function parseTagColour(raw: string | null | undefined): TagColour | null {
  const match = /^([a-z]+)(?:-([123]))?$/.exec((raw ?? '').trim().toLowerCase())
  if (!match) return null
  const tone = isTagTone(match[1]) ? match[1] : ALIASES[match[1]]
  if (!tone) return null
  return { tone, tier: (Number(match[2] ?? 1) as TagTier) }
}

export function tagColourKey(colour: TagColour): string {
  return colour.tier === 1 ? colour.tone : `${colour.tone}-${colour.tier}`
}

/** The face classes (`index.css`, `.tag-*`): the tone's variables, and the step. */
export function tagToneClass(colour: TagColour | TagTone): string {
  const { tone, tier } = typeof colour === 'string' ? { tone: colour, tier: 1 } : colour
  return tier === 1 ? `tag-${tone}` : `tag-${tone} tag-t${tier}`
}

/** Every colour the picker offers: a row per step, the wheel then the greys across it. */
export const TAG_SWATCHES: readonly TagColour[] = TAG_TIERS.flatMap((tier) =>
  TAG_TONES.map((tone) => ({ tone, tier })),
)
